// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** Who looks after a live admission: where the patient is and the treating doctor, never the clinical record. */
export interface TreatingDoctorRowOut {
  admission_id: number;
  admission_number: string;
  admission_type: "Standard" | "Emergency" | "CodeRed" | "Overflow" | "Planned";
  status: "AdmissionPending" | "Waitlisted" | "BedReserved" | "CodeRedActive" | "Admitted" | "DischargeInProgress" | "Discharged" | "Cancelled";
  patient_id: number;
  mrn: string;
  patient_name: string;
  ward_name: string | null;
  bed_label: string | null;
  /** Null: a Code Red waiting for a doctor (decisions 57) */
  primary_doctor_id: number | null;
  primary_doctor_name: string | null;
  /** When the treating doctor took the patient; null without one */
  doctor_since: string | null;
}

export interface TreatingDoctorOut {
  admission_id: number;
  admission_number: string;
  admission_type: "Standard" | "Emergency" | "CodeRed" | "Overflow" | "Planned";
  status: "AdmissionPending" | "Waitlisted" | "BedReserved" | "CodeRedActive" | "Admitted" | "DischargeInProgress" | "Discharged" | "Cancelled";
  patient_id: number;
  mrn: string;
  patient_name: string;
  ward_name: string | null;
  bed_label: string | null;
  /** Null: a Code Red waiting for a doctor (decisions 57) */
  primary_doctor_id: number | null;
  primary_doctor_name: string | null;
  /** When the treating doctor took the patient; null without one */
  doctor_since: string | null;
  /** Every change of the treating doctor, oldest first */
  changes: DoctorChangeOut[];
}

/** One change of the treating doctor (decisions 58), kept for the medico-legal record. */
export interface DoctorChangeOut {
  change_id: number;
  /** TakeOver: a doctor gave an admission without one its doctor; Handover: the treating doctor handed the patient over; Reassigned: the Hospital Admin, while the treating doctor was away */
  kind: "TakeOver" | "Handover" | "Reassigned";
  /** Null when the admission had no doctor */
  from_doctor_id: number | null;
  from_doctor_name: string | null;
  to_doctor_id: number;
  to_doctor_name: string;
  reason: string;
  changed_by_name: string;
  changed_at: string;
}

export interface TreatingDoctorIn {
  /** The doctor who takes the patient over: an active doctor registered with the PMDC (employee_id from GET /staff/lookup?license_type=PMDC) */
  doctor_id: number;
  /** Why the patient changes doctor (the medico-legal record) */
  reason: string;
}

/** One active staff member as a picker shows them (GET /staff/lookup): the facts on their badge and the registration their stamp prints, nothing else. */
export interface StaffLookupOut {
  /** The id a form's staff field takes (contrast_doctor_id, employee_id, ...) */
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  department_name: string | null;
  /** The council they are registered with (PMDC: a doctor or dentist; PNC: a nurse); null: none */
  license_type: "PMDC" | "PNC" | "Other" | null;
  /** As their stamp prints it, e.g. "PMDC 12345-P"; null: no number on file */
  registration: string | null;
  /** Their login, the id a form's user field takes (an action's owner, a signer, the person told); null: no login (decision 62) */
  user_id: number | null;
}

/** The live admissions and their treating doctors — GET /api/v1/ipd/treating-doctors (who may call: holders of ipd.admission.view or ipd.admission.reassign). */
export function listTreatingDoctors(query?: { doctor_id?: number | null; waiting?: boolean }): Promise<TreatingDoctorRowOut[]> {
  return api<TreatingDoctorRowOut[]>("GET", withQuery(`/ipd/treating-doctors`, query), undefined);
}

/** An inpatient's treating doctor and every change of it — GET /api/v1/admissions/{admission_id}/treating-doctor (who may call: holders of ipd.admission.view or ipd.admission.reassign). */
export function getTreatingDoctor(admission_id: number): Promise<TreatingDoctorOut> {
  return api<TreatingDoctorOut>("GET", `/admissions/${admission_id}/treating-doctor`, undefined);
}

/** Hand an inpatient over to another doctor — POST /api/v1/admissions/{admission_id}/treating-doctor (who may call: holders of ipd.admission.request or ipd.admission.reassign). */
export function changeTreatingDoctor(admission_id: number, body: TreatingDoctorIn): Promise<TreatingDoctorOut> {
  return api<TreatingDoctorOut>("POST", `/admissions/${admission_id}/treating-doctor`, body, { idempotent: true });
}

/** Find a staff member for a form (badge facts only) — GET /api/v1/staff/lookup (who may call: any logged-in user). */
export function lookupStaff(query: { q: string; department_id?: number | null; license_type?: "PMDC" | "PNC" | null; limit?: number }): Promise<StaffLookupOut[]> {
  return api<StaffLookupOut[]>("GET", withQuery(`/staff/lookup`, query), undefined);
}
